    @Override
    public void setupAnim(T entity, float limbSwing, float limbSwingAmount,
                          float ageInTicks, float netHeadYaw, float headPitch) {
        this.head.yRot = netHeadYaw * ((float) Math.PI / 180F);
        this.head.xRot = headPitch * ((float) Math.PI / 180F) + 0.15F;
        float amount = Math.min(limbSwingAmount, 1.0F);
        float cycle = limbSwing * 0.6662F * 1.10F;
        float stride = (float) Math.cos(cycle) * 0.35F * amount;
        this.legFrontLeft.xRot = stride;
        this.legBackRight.xRot = stride;
        this.legFrontRight.xRot = -stride;
        this.legBackLeft.xRot = -stride;
        this.armLeft.xRot = (float) Math.cos(cycle) * 0.17F * amount + (float) Math.sin(ageInTicks * 0.06F) * 0.08F;
        this.armRight.xRot = -(float) Math.cos(cycle) * 0.17F * amount + (float) Math.sin(ageInTicks * 0.06F) * 0.08F;
        this.abdomen0.xRot = -0.90F + (float) Math.sin(ageInTicks * 0.07F) * 0.06F;
        this.root.y = (float) Math.abs(Math.sin(cycle)) * 0.90F * amount;
        this.root.zRot = (float) Math.sin(cycle) * 0.03F * amount;
    }

    @Override
    public void renderToBuffer(PoseStack pose, VertexConsumer buffer, int light,
                               int overlay, int colour) {
        this.root.render(pose, buffer, light, overlay, colour);
    }
